// A04_PAGES_v1 — স্বয়ংসম্পূর্ণ অফলাইন টেস্ট স্যুট (কোনো বাহ্যিক ডিপেনডেন্সি ছাড়া)
// যাচাই করে:
// ১. __FZ_ON_PAGES4 সুইচ বন্ধ (OFF) থাকলে আউটপুট পূর্বের সাথে বাইট-ফর-বাইট অভিন্ন থাকে।
// ২. __FZ_ON_PAGES4 সুইচ চালু (ON) থাকলে a04 নমুনার ৪টি পৃষ্ঠার প্রতিটি ১টি করে পৃষ্ঠায় আবদ্ধ থাকে এবং মোট পৃষ্ঠা ৪ হয়।

import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import zlib from 'node:zlib';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const rootDir = path.resolve(__dirname, '..');

let passed = 0;
let failed = 0;

function assert(cond, msg) {
  if (cond) {
    passed++;
  } else {
    failed++;
    console.error(`❌ ব্যর্থ: ${msg}`);
  }
}

// প্রদত্ত ফ্ল্যাগ অবস্থায় ইঞ্জিন লোড করার সহায়ক ফাংশন
function loadEngine(pages4Enabled, envFlag = false, extraFlags = {}) {
  const sandbox = {
    console,
    Math,
    Date,
    Uint8Array,
    ArrayBuffer,
    DataView,
    Buffer,
    Promise,
    Array,
    Object,
    String,
    Number,
    Boolean,
    RegExp,
    JSON,
    Error,
    Map,
    Set,
    parseInt,
    parseFloat,
    isNaN,
    isFinite
  };
  sandbox.window = sandbox;
  sandbox.globalThis = sandbox;
  if (pages4Enabled) {
    sandbox.window.__FZ_ON_PAGES4 = true;
  }
  Object.assign(sandbox.window, extraFlags);
  if (envFlag) {
    sandbox.process = { env: { FZ_ON: 'PAGES4' } };
  }

  const files = [
    'js/layout-engine/faithful/layout-ir.js',
    'js/layout-engine/faithful/line-fit.js',
    'js/layout-engine/faithful/faithful-docx-builder.js'
  ];

  vm.createContext(sandbox);
  for (const rel of files) {
    const code = fs.readFileSync(path.join(rootDir, rel), 'utf8');
    vm.runInContext(code, sandbox, { filename: rel });
  }
  return sandbox;
}

// পৃষ্ঠার সব আইটেম বের করার সহায়ক ফাংশন
function getPageItems(pg) {
  return (pg.bands || []).flatMap(b => (b.cells || []).flatMap(c => c.items || []));
}

// প্রদত্ত IR এবং বডি XML থেকে Word-এর পৃষ্ঠা বিভাজন ও উচ্চতা সিমুলেশন করার ফাংশন
function simulateWordPages(eng, ir) {
  eng.__FZ_PLANLOG = [];
  const res = eng.FayzarFaithfulDocx.bodyXml(ir);
  const xml = typeof res === 'string' ? res : res.xml;
  const planLogs = eng.__FZ_PLANLOG || [];

  const sectMatches = xml.match(/<w:sectPr>/g) || [];
  const pageBreakMatches = xml.match(/<w:pageBreakBefore\/>/g) || [];

  const pageSummaries = ir.pages.map((pg, idx) => {
    const pl = eng.FayzarFaithfulDocx.planPage(pg);
    const log = planLogs[idx] || {};
    const mb0 = pg.margins.bottom;
    const sectBottom = pg.frame ? mb0 : Math.min(mb0, Math.max(10, mb0 - 36));
    const realLimit = log.realLimit || (pg.heightPt - sectBottom);
    const boxExtra = (pg.boxes || []).reduce((a, b) => a + 2 * (b.sz || 6) / 8, 0);
    const finalEnd = pg.margins.top + pl.els.reduce((a, e) => a + e.before * pl.f + e.h, 0) + boxExtra;
    const fitsInOnePage = finalEnd <= realLimit + 0.5;
    return {
      pageNumber: idx + 1,
      heightPt: pg.heightPt,
      realLimit,
      planEnd: finalEnd,
      fitsInOnePage
    };
  });

  const totalWordPages = pageSummaries.reduce((sum, p) => {
    if (p.fitsInOnePage) return sum + 1;
    return sum + Math.ceil(p.planEnd / p.realLimit);
  }, 0);

  return {
    xml,
    sectCount: sectMatches.length,
    pageBreakBeforeCount: pageBreakMatches.length,
    pageSummaries,
    totalWordPages
  };
}

// ডেটা ফাইল লোড করা (qa/golden-data/asis/a04 অথবা বিকল্প পাথ)
const dataDirCandidates = [
  path.join(rootDir, 'qa/golden-data/asis/a04'),
  path.join(rootDir, 'test-results/faithful/a04')
];
const dataDir = dataDirCandidates.find(d => fs.existsSync(path.join(d, 'capture.json'))) || dataDirCandidates[0];

const capturePath = path.join(dataDir, 'capture.json');
const measuresPath = path.join(dataDir, 'measures.json');
const savedIrPath = path.join(dataDir, 'ir.json');

const EMBEDDED_CAP_GZ = "";
const EMBEDDED_MEAS_GZ = "";
const EMBEDDED_IR_GZ = "";

function loadJsonOrFallback(filePath, gzB64) {
  if (fs.existsSync(filePath)) {
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  }
  return JSON.parse(zlib.gunzipSync(Buffer.from(gzB64, 'base64')).toString('utf8'));
}

const captureData = loadJsonOrFallback(capturePath, EMBEDDED_CAP_GZ);
const measuresFile = loadJsonOrFallback(measuresPath, EMBEDDED_MEAS_GZ);
const savedIrData = loadJsonOrFallback(savedIrPath, EMBEDDED_IR_GZ);

// ============================================================================
// ১. সুইচ বন্ধ (OFF) অবস্থায় আচরণ যাচাই
// ============================================================================
{
  const engOff1 = loadEngine(false, false);
  const engOff2 = loadEngine(false, false);

  // ১.১ capture + measures থেকে নতুন IR তৈরি ও ডকএক্স বিল্ড
  const irOffFromMeasures = engOff1.FayzarLayoutIR.build(
    measuresFile.cap || captureData,
    measuresFile.measures,
    measuresFile.pageInfo
  );
  engOff1.FayzarLineFit.fit(irOffFromMeasures);
  const resOff1 = engOff1.FayzarFaithfulDocx.bodyXml(irOffFromMeasures);
  const bytesOffFromMeasures = await engOff1.FayzarFaithfulDocx.build(irOffFromMeasures, {
    JSZip: engOff1.FayzarFaithfulDocx.MiniJSZip,
    type: 'uint8array'
  });

  // ১.২ পুনরায় চালানো হলে সম্পূর্ণ অভিন্ন আউটপুট নিশ্চিতকরণ
  const irOffRepeat = engOff2.FayzarLayoutIR.build(
    measuresFile.cap || captureData,
    measuresFile.measures,
    measuresFile.pageInfo
  );
  engOff2.FayzarLineFit.fit(irOffRepeat);
  const resOff2 = engOff2.FayzarFaithfulDocx.bodyXml(irOffRepeat);

  assert(
    JSON.stringify(irOffFromMeasures) === JSON.stringify(irOffRepeat),
    'সুইচ OFF থাকলে LayoutIR.build আউটপুট শতভাগ অভিন্ন হতে হবে'
  );
  assert(
    resOff1.xml === resOff2.xml,
    'সুইচ OFF থাকলে FaithfulDocx.bodyXml আউটপুট বাইট-ফর-বাইট অভিন্ন হতে হবে'
  );
  assert(
    bytesOffFromMeasures instanceof engOff1.Uint8Array && bytesOffFromMeasures.length > 5000,
    'সুইচ OFF থাকলে বৈধ DOCX বাইনারি উৎপন্ন হতে হবে'
  );

  // ১.৩ সংরক্ষিত ir.json এর সাথে সুইচ OFF অবস্থায় আচরণ যাচাই
  const irSavedClone = JSON.parse(JSON.stringify(savedIrData));
  const resOffSaved = engOff1.FayzarFaithfulDocx.bodyXml(irSavedClone);

  assert(
    irSavedClone.pages.length === 4,
    'মূল নথিতে ৪টি পৃষ্ঠা থাকতে হবে'
  );
  // সুইচ OFF অবস্থায় পৃষ্ঠা ১ ও পৃষ্ঠা ২-এর টেবিল ফন্ট বড় (১৫pt এবং ১৭.৫pt) থাকে
  const p1TableOff = getPageItems(irSavedClone.pages[0]).find(b => b.kind === 'table');
  const p2TableOff = getPageItems(irSavedClone.pages[1]).find(b => b.kind === 'table');
  assert(
    p1TableOff.fontPt === 15 && p2TableOff.fontPt === 17.5,
    'সুইচ OFF অবস্থায় সংরক্ষিত IR-এ পুরাতন টেবিল ফন্ট সাইজ (15pt ও 17.5pt) অপরিবর্তিত থাকতে হবে'
  );
  assert(
    resOffSaved.xml.includes('w:left w:w="108"') && !resOffSaved.xml.includes('w:left w:w="20"'),
    'সুইচ OFF অবস্থায় ডিফল্ট ১০৮ dxa (৫.৪pt) সেল প্যাডিং অপরিবর্তিত থাকতে হবে'
  );
}

// ============================================================================
// ২. সুইচ চালু (ON) অবস্থায় আচরণ যাচাই (window.__FZ_ON_PAGES4 = true)
// ============================================================================
{
  const engOn = loadEngine(true, false);

  // ২.১ capture.json + measures.json থেকে সম্পূর্ণ পাইপলাইন যাচাই
  const irOn = engOn.FayzarLayoutIR.build(
    measuresFile.cap || captureData,
    measuresFile.measures,
    measuresFile.pageInfo
  );
  engOn.FayzarLineFit.fit(irOn);
  const simOn = simulateWordPages(engOn, irOn);
  const xmlOn = simOn.xml;

  assert(irOn.pages.length === 4, 'সুইচ ON থাকলে IR-এ পৃষ্ঠা সংখ্যা ৪ হতে হবে');
  assert(simOn.sectCount === 4, 'সুইচ ON থাকলে DOCX-এ ঠিক ৪টি <w:sectPr> থাকতে হবে');
  assert(
    simOn.pageBreakBeforeCount === 0,
    'সুইচ ON থাকলে পৃষ্ঠার মাঝখানে কোনো অতিরিক্ত <w:pageBreakBefore/> থাকা যাবে না'
  );
  assert(
    simOn.totalWordPages === 4,
    `সুইচ ON থাকলে মোট Word পৃষ্ঠা সংখ্যা ঠিক ৪ হতে হবে (পাওয়া গেছে: ${simOn.totalWordPages})`
  );

  // প্রতিটি পৃষ্ঠার উচ্চতা তার সীমা (realLimit) এর মধ্যে আছে কি না যাচাই
  for (const ps of simOn.pageSummaries) {
    assert(
      ps.fitsInOnePage,
      `পৃষ্ঠা ${ps.pageNumber} এর উচ্চতা (${ps.planEnd.toFixed(1)}pt) সীমার (${ps.realLimit.toFixed(1)}pt) মধ্যে থাকতে হবে`
    );
  }

  // ২.২ পৃষ্ঠা ১-এর নির্দিষ্ট রুট-কজ সমাধান যাচাই
  const p1Table = getPageItems(irOn.pages[0]).find(b => b.kind === 'table');
  assert(
    p1Table.fontPt <= 8,
    `পৃষ্ঠা ১-এর টেবিলের ফন্ট সাইজ ৮pt বা তার নিচে হতে হবে (পাওয়া গেছে: ${p1Table.fontPt}pt)`
  );
  assert(
    p1Table.rows[0][2] === '' && String(p1Table.rows[1][2] || '').includes('যতদিন চাকুরী করা হইয়াছে'),
    'পৃষ্ঠা ১-এর টেবিলের প্রথম সারির ৩য় কলামের দীর্ঘ শিরোনাম নিচের বিবরণী সারিতে স্থানান্তরিত হতে হবে'
  );
  const p1BodyRowH = p1Table.rowHeightsPt.slice(4);
  assert(
    p1BodyRowH.every(h => h >= 15 && h <= 22),
    'পৃষ্ঠা ১-এর টেবিলের ২০টি "দিন" সারির উচ্চতা সুষমভাবে ১৫–২২pt এর মধ্যে বণ্টিত হতে হবে'
  );

  // ২.৩ পৃষ্ঠা ২-এর নির্দিষ্ট রুট-কজ সমাধান যাচাই
  const p2Items = getPageItems(irOn.pages[1]);
  const p2Title = p2Items[0];
  const p2Table = p2Items.find(b => b.kind === 'table');
  assert(
    p2Title.fontPt <= 40,
    `পৃষ্ঠা ২-এর "৬২" শিরোনামের ফন্ট সাইজ ৪০pt এর বেশি হতে পারবে না (পাওয়া গেছে: ${p2Title.fontPt}pt)`
  );
  assert(
    p2Table.fontPt <= 7.5,
    `পৃষ্ঠা ২-এর টেবিলের ফন্ট সাইজ ৭.৫pt বা তার নিচে হতে হবে (পাওয়া গেছে: ${p2Table.fontPt}pt)`
  );
  assert(
    p2Table.colFractions[0] >= 0.04,
    `পৃষ্ঠা ২-এর টেবিলের ১ম কলামের প্রস্থ অন্তত ৪.০% (~২৫pt) হতে হবে যেন "মাস"/"দিন" না ভাঙে (পাওয়া গেছে: ${(p2Table.colFractions[0] * 100).toFixed(2)}%)`
  );
  assert(
    xmlOn.includes('w:left w:w="20"'),
    'ঘন রেজিস্টার টেবিলে সরু কলামের র‍্যাপিং রোধে সেল প্যাডিং ২০ dxa (১pt) হতে হবে'
  );

  // ২.৪ পৃষ্ঠা ৩-এর নির্দিষ্ট রুট-কজ সমাধান যাচাই
  const p3Items = getPageItems(irOn.pages[2]);
  const p3TabifiedProse = p3Items.filter(
    b => b.text && b.text.length > 60 && b.tabLines && b.tabLines.length > 0
  );
  assert(
    p3TabifiedProse.length === 0,
    'পৃষ্ঠা ৩-এর দীর্ঘ প্রবাহমান গদ্য অনুচ্ছেদে ভুয়া ট্যাব স্টপ (tabify) থাকা যাবে না'
  );
  const p3Block30 = p3Items.find(b => b.text && b.text.startsWith('(২) যে ছুটি পূর্ণ বেতনের গড়ে'));
  assert(
    p3Block30 && p3Block30.rect.w >= 450 && p3Block30.fontPt >= 12,
    'পৃষ্ঠা ৩-এর শেষের (২) অনুচ্ছেদের খণ্ডিত বক্স প্রস্থ সংশোধিত (>=450pt) ও ফন্ট সাইজ স্বাভাবিক (>=12pt) থাকতে হবে'
  );

  // ২.৫ পৃষ্ঠা ৪-এর নির্দিষ্ট রুট-কজ সমাধান যাচাই
  const p4Items = getPageItems(irOn.pages[3]);
  const p4LongParas = p4Items.filter(b => b.text && b.text.length > 300);
  assert(
    p4LongParas.length === 5 && p4LongParas.every(b => b.fontPt >= 11),
    'পৃষ্ঠা ৪-এর ৫টি দীর্ঘ অনুচ্ছেদের ফন্ট সাইজ ১১pt বা তার ওপরে থাকতে হবে'
  );
}

// ============================================================================
// ৩. সংরক্ষিত ir.json সরাসরি ব্যবহার করলেও সুইচ ON অবস্থায় ৪ পৃষ্ঠা নিশ্চিতকরণ
// ============================================================================
{
  const engOnEnv = loadEngine(false, true); // process.env.FZ_ON = 'PAGES4' দিয়ে পরীক্ষা
  const irSavedOn = JSON.parse(JSON.stringify(savedIrData));
  engOnEnv.FayzarLineFit.fit(irSavedOn);
  const simSavedOn = simulateWordPages(engOnEnv, irSavedOn);

  assert(
    simSavedOn.totalWordPages === 4,
    `সংরক্ষিত ir.json-এও FZ_ON=PAGES4 চালু থাকলে মোট পৃষ্ঠা সংখ্যা ৪ হতে হবে (পাওয়া গেছে: ${simSavedOn.totalWordPages})`
  );
  assert(
    simSavedOn.pageSummaries.every(p => p.fitsInOnePage),
    'সংরক্ষিত ir.json-এর প্রতিটি পৃষ্ঠা ১টি করে Word পৃষ্ঠায় ফিট হতে হবে'
  );
  assert(
    simSavedOn.xml.includes('w:left w:w="20"'),
    'সংরক্ষিত ir.json-এও ঘন রেজিস্টার টেবিলে ১pt (২০ dxa) সেল প্যাডিং প্রযুক্ত হতে হবে'
  );
}

// ============================================================================
// ৪. A07_TABLECOL ও WRAPFIT-এর সাথে A04_PAGES4-এর সহাবস্থান (Rebase v2) যাচাই
// ============================================================================
{
  const engBoth = loadEngine(true, false, { __FZ_ON_TABLECOL: true, __FZ_ON_WRAPFIT: true });
  const irBoth = engBoth.FayzarLayoutIR.build(
    measuresFile.cap || captureData,
    measuresFile.measures,
    measuresFile.pageInfo
  );
  engBoth.FayzarLineFit.fit(irBoth);
  const simBoth = simulateWordPages(engBoth, irBoth);

  assert(
    simBoth.totalWordPages === 4,
    `TABLECOL + WRAPFIT + PAGES4 একসাথে চালু থাকলেও মোট Word পৃষ্ঠা সংখ্যা ৪ হতে হবে (পাওয়া গেছে: ${simBoth.totalWordPages})`
  );
  assert(
    simBoth.pageSummaries.every(p => p.fitsInOnePage),
    'TABLECOL + WRAPFIT + PAGES4 একসাথে চালু থাকলেও প্রতিটি পৃষ্ঠা ১টি করে Word পৃষ্ঠায় আবদ্ধ থাকতে হবে'
  );
  const p1TblBoth = getPageItems(irBoth.pages[0]).find(b => b.kind === 'table');
  const p2TblBoth = getPageItems(irBoth.pages[1]).find(b => b.kind === 'table');
  assert(
    p1TblBoth.fontPt <= 8 && p2TblBoth.fontPt <= 7.5,
    'TABLECOL + PAGES4 একসাথে চালু থাকলেও পৃষ্ঠা ১ ও ২-এর রেজিস্টার ছকের ফন্ট সাইজ (<=8pt ও <=7.5pt) সংরক্ষিত থাকতে হবে'
  );
  assert(
    !p1TblBoth.lineSpacingPt && !p2TblBoth.lineSpacingPt,
    'TABLECOL + PAGES4 একসাথে চালু থাকলে ঘন রেজিস্টার ছকে আংশিক হেডার-ব্যান্ড থেকে ভুয়া lineSpacingPt প্রয়োগ হবে না'
  );
  assert(
    Math.max(...p1TblBoth.rows.map(r => r.length)) === 17 && Math.max(...p2TblBoth.rows.map(r => r.length)) === 12,
    'TABLECOL + PAGES4 একসাথে চালু থাকলেও ১৭ ও ১২ কলামের রেজিস্টার ছকের কলাম-সংখ্যা অক্ষুণ্ণ থাকতে হবে'
  );
}

console.log(`ফলাফল: ${passed} পাস, ${failed} ব্যর্থ`);
if (failed > 0) {
  process.exit(1);
}
